import { existsSync, readFileSync } from "node:fs";
import { join, relative, sep } from "node:path";
import { UI_PARTS, type UiPartSpec } from "@capybara-hq/plugin-sdk";
import {
  type Finding,
  isParseError,
  listSourceFiles,
  type Node,
  parseFile,
  walk,
} from "./source.js";

export type { Finding };

/** Where the generated files live, relative to the repository root. */
export const DESIGN_PARTS_TS = "packages/design/src/ui-parts.generated.ts";
export const PLUGIN_CLIENT_PARTS_TS = "packages/plugin-client/src/ui-parts.generated.ts";
export const UI_PARTS_DOC = "docs/guide/ui-parts.md";

const HEADER = "// Generated by pnpm gen:ui-parts from @capybara-hq/plugin-sdk; do not edit.";

/** `<head>[…]<tail>`, one item per line (biome's layout) when it does not fit in 100 columns. */
function declareList(head: string, values: readonly string[], tail: string): string {
  const items = values.map((v) => JSON.stringify(v));
  const one = `${head}[${items.join(", ")}]${tail}`;
  if (one.length <= 100) return one;
  return [`${head}[`, ...items.map((i) => `  ${i},`), `]${tail}`].join("\n");
}

function renderNames(parts: readonly UiPartSpec[], docLine: string): string {
  const names = parts.map((p) => p.name);
  return [
    HEADER,
    "",
    `export type UiPartName =\n  | ${names.map((n) => JSON.stringify(n)).join("\n  | ")};`,
    "",
    docLine,
    declareList("export const UI_PART_NAMES: readonly UiPartName[] = ", names, ";"),
    "",
  ].join("\n");
}

/** The generated design-package copy of the part names (design imports no SDK). */
export function renderDesignUiPartsTs(parts: readonly UiPartSpec[]): string {
  return renderNames(parts, "/** Every `data-cap-part` name the design system may render. */");
}

/** The generated `@capybara-hq/plugin-client` copy of the part names. */
export function renderPluginClientUiPartsTs(parts: readonly UiPartSpec[]): string {
  return renderNames(parts, "/** Every part name plugin CSS and components may rely on. */");
}

const code = (values: readonly string[]) =>
  values.length === 0 ? "none" : values.map((v) => `\`${v}\``).join(", ");

/** The generated docs page: a table of every part and a section per part. */
export function renderUiPartsDoc(parts: readonly UiPartSpec[]): string {
  const rows = parts.map(
    (p) => `| \`${p.name}\` | ${p.version} | ${code(p.states)} | ${p.description.en} |`,
  );
  const sections = parts.map((p) =>
    [
      `## \`${p.name}\``,
      "",
      p.description.en,
      "",
      `- Version: ${p.version}`,
      `- States: ${code(p.states)}`,
      `- Owner: ${code(p.owner)}`,
      `- Selector: \`[data-cap-part~="${p.name}"]\``,
      "",
    ].join("\n"),
  );
  return [
    "<!-- Generated by pnpm gen:ui-parts from @capybara-hq/plugin-sdk; do not edit. -->",
    "",
    "# UI parts",
    "",
    "The built-in elements plugin CSS may select. Each carries a literal `data-cap-part` attribute,",
    'which may hold several names; select with `[data-cap-part~="<name>"]`.',
    "",
    "| Part | Version | States | Element |",
    "|---|---|---|---|",
    ...rows,
    "",
    ...sections,
  ].join("\n");
}

function staleFindings(root: string, parts: readonly UiPartSpec[]): Finding[] {
  const out: Finding[] = [];
  for (const [rel, expected] of [
    [DESIGN_PARTS_TS, renderDesignUiPartsTs(parts)],
    [PLUGIN_CLIENT_PARTS_TS, renderPluginClientUiPartsTs(parts)],
    [UI_PARTS_DOC, renderUiPartsDoc(parts)],
  ] as const) {
    const file = join(root, rel);
    const actual = existsSync(file) ? readFileSync(file, "utf8") : undefined;
    if (actual === expected) continue;
    const a = (actual ?? "").split("\n");
    const e = expected.split("\n");
    let line = 0;
    while (line < e.length && a[line] === e[line]) line++;
    out.push({
      file,
      line: line + 1,
      rule: "ui-parts-stale",
      message:
        actual === undefined
          ? `${rel} is missing; run pnpm gen:ui-parts`
          : `${rel} differs from the SDK part catalog; run pnpm gen:ui-parts (never edit it by hand)`,
    });
  }
  return out;
}

/** The trees scanned for `data-cap-part`; `dev/` pages of apps/web are not the product's own UI. */
const SCAN_DIRS = ["packages/design/src", "apps/web/src"];

interface Render {
  file: string;
  line: number;
  /** Repository-relative, forward slashes. */
  rel: string;
  tokens: string[];
}

/** The string a literal value (or a template without expressions) holds, else undefined. */
function stringOf(n: Node | null | undefined): string | undefined {
  if (!n) return undefined;
  if (n.type === "Literal" && typeof n.value === "string") return n.value;
  if (n.type === "TemplateLiteral" && (n.expressions as Node[]).length === 0) {
    const cooked = ((n.quasis as Node[])[0]?.value as { cooked?: string } | undefined)?.cooked;
    return typeof cooked === "string" ? cooked : undefined;
  }
  return undefined;
}

/**
 * Every literal the attribute can hold: a string, or a conditional whose branches are strings (a
 * `button.primary` that depends on the variant is still statically known). Undefined = dynamic.
 */
function literalsOf(value: Node | null | undefined): string[] | undefined {
  if (!value) return undefined;
  const inner = value.type === "JSXExpressionContainer" ? (value.expression as Node) : value;
  const one = stringOf(inner);
  if (one !== undefined) return [one];
  if (inner.type === "ConditionalExpression") {
    const a = literalsOf(inner.consequent as Node);
    const b = literalsOf(inner.alternate as Node);
    return a && b ? [...a, ...b] : undefined;
  }
  return undefined;
}

/**
 * Every `data-cap-part` JSX attribute under the scanned trees, and every `"data-cap-part"` key of an
 * object literal there (props spread onto an element); a non-literal value is reported. Props that
 * arrive from elsewhere (a caller's `{...rest}`) cannot be seen statically.
 */
function collectRenders(root: string, out: Finding[]): Render[] {
  const renders: Render[] = [];
  for (const dir of SCAN_DIRS) {
    const base = join(root, dir);
    for (const { file } of listSourceFiles(base)) {
      if (!file.endsWith(".tsx")) continue;
      if (dir.startsWith("apps/web") && relative(base, file).split(sep)[0] === "dev") continue;
      const p = parseFile(file);
      if (isParseError(p)) {
        out.push(p);
        continue;
      }
      const rel = relative(root, file).split(sep).join("/");
      walk(p.program, (n) => {
        // the attribute, or an object literal's "data-cap-part" key (props spread onto an element)
        if (n.type === "JSXAttribute") {
          const name = n.name as Node;
          if (name.type !== "JSXIdentifier" || name.name !== "data-cap-part") return;
        } else if (n.type === "Property") {
          if (n.computed === true || stringOf(n.key as Node) !== "data-cap-part") return;
        } else return;
        const line = p.lineOf(n.start);
        const lits = literalsOf(n.value as Node | null | undefined);
        if (lits === undefined) {
          out.push({
            file,
            line,
            rule: "ui-part-literal",
            message:
              'data-cap-part must be a string literal (or a conditional of literals) so the check can match it to the catalog; write data-cap-part="<name>"',
          });
          return;
        }
        renders.push({
          file,
          line,
          rel,
          tokens: lits.flatMap((l) => l.split(/\s+/).filter(Boolean)),
        });
      });
    }
  }
  return renders;
}

/**
 * check:ui-parts: every `data-cap-part` literal under packages/design/src and apps/web/src names a
 * catalog part (`ui-part-undeclared`) and sits in one of that part's owner files (`ui-part-owner`);
 * every catalog part has a literal in an owner file (`ui-part-unrendered`); a value that is not a
 * literal is refused (`ui-part-literal`). Against the real catalog the generated copies and the
 * docs page must equal what gen:ui-parts renders (`ui-parts-stale`).
 */
export function checkUiParts(root: string, parts: readonly UiPartSpec[] = UI_PARTS): Finding[] {
  const out: Finding[] = [];
  const renders = collectRenders(root, out);
  const byName = new Map(parts.map((p) => [p.name as string, p]));
  const rendered = new Set<string>();
  for (const r of renders) {
    for (const token of new Set(r.tokens)) {
      const spec = byName.get(token);
      if (!spec) {
        out.push({
          file: r.file,
          line: r.line,
          rule: "ui-part-undeclared",
          message: `"${token}" is not a part of the catalog (packages/plugin-sdk/src/ui-parts.ts); add it there first`,
        });
      } else if (!spec.owner.includes(r.rel)) {
        out.push({
          file: r.file,
          line: r.line,
          rule: "ui-part-owner",
          message: `part "${token}" belongs to ${spec.owner.join(", ")}; render it there or add this file to its owner list`,
        });
      } else rendered.add(token);
    }
  }
  for (const spec of parts) {
    if (rendered.has(spec.name)) continue;
    out.push({
      file: join(root, spec.owner[0] ?? ""),
      line: 1,
      rule: "ui-part-unrendered",
      message: `part "${spec.name}" has no literal data-cap-part="${spec.name}" in its owner files; render it there`,
    });
  }
  if (parts === UI_PARTS) out.push(...staleFindings(root, parts));
  return out;
}
